alter table public.officeflow_client_groups enable row level security;
alter table public.officeflow_client_group_members enable row level security;
alter table public.officeflow_matters enable row level security;
alter table public.officeflow_matter_rounds enable row level security;
alter table public.officeflow_matter_type_config enable row level security;
alter table public.officeflow_task_status_history enable row level security;
drop policy if exists officeflow_workspace_member_access on public.officeflow_client_groups;
create policy officeflow_workspace_member_access on public.officeflow_client_groups for all using (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid())))) with check (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid()))));
drop policy if exists officeflow_workspace_member_access on public.officeflow_matters;
create policy officeflow_workspace_member_access on public.officeflow_matters for all using (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid())))) with check (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid()))));
drop policy if exists officeflow_workspace_member_access on public.officeflow_matter_type_config;
create policy officeflow_workspace_member_access on public.officeflow_matter_type_config for all using (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid())))) with check (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid()))));
drop policy if exists officeflow_workspace_member_access on public.officeflow_task_status_history;
create policy officeflow_workspace_member_access on public.officeflow_task_status_history for all using (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid())))) with check (exists(select 1 from public.officeflow_workspaces w where w.id=workspace_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid()))));
drop policy if exists officeflow_workspace_member_access on public.officeflow_client_group_members;
create policy officeflow_workspace_member_access on public.officeflow_client_group_members for all using (exists(select 1 from public.officeflow_client_groups g join public.officeflow_workspaces w on w.id=g.workspace_id where g.id=group_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid())))) with check (exists(select 1 from public.officeflow_client_groups g join public.officeflow_workspaces w on w.id=g.workspace_id where g.id=group_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid()))));
drop policy if exists officeflow_workspace_member_access on public.officeflow_matter_rounds;
create policy officeflow_workspace_member_access on public.officeflow_matter_rounds for all using (exists(select 1 from public.officeflow_matters x join public.officeflow_workspaces w on w.id=x.workspace_id where x.id=matter_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid())))) with check (exists(select 1 from public.officeflow_matters x join public.officeflow_workspaces w on w.id=x.workspace_id where x.id=matter_id and (w.owner_id=auth.uid() or exists(select 1 from public.officeflow_workspace_members m where m.workspace_owner_id=w.owner_id and m.user_id=auth.uid()))));